<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Teacher'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$assessmentId=filter_var($_POST['assessment_id']??null,FILTER_VALIDATE_INT);$scores=$_POST['scores']??[];
if(!$assessmentId||!is_array($scores)){$_SESSION['error']='Assessment record is invalid.';header('Location: ../?page=academics&tab=assessments');exit;}
$pdo=db();$q=$pdo->prepare('SELECT a.id,a.max_mark,a.class_id,a.subject_id,t.academic_year,t.starts_on,t.ends_on,c.form_level,c.stream,c.academic_year AS class_year,cs.teacher_id,c.class_teacher_id FROM assessments a JOIN school_terms t ON t.id=a.term_id JOIN class_groups c ON c.id=a.class_id JOIN class_subjects cs ON cs.class_id=a.class_id AND cs.subject_id=a.subject_id WHERE a.id=:id');$q->execute(['id'=>$assessmentId]);$assessment=$q->fetch();
if(!$assessment||(int)$assessment['class_year']!==(int)$assessment['academic_year']){$_SESSION['error']='Assessment was not found or its class year does not match the term.';header('Location: ../?page=academics&tab=assessments');exit;}
if($user['role']==='Teacher'&&(int)$assessment['teacher_id']!==(int)$user['id']&&(int)$assessment['class_teacher_id']!==(int)$user['id']){http_response_code(403);exit('You are not assigned to this assessment.');}
$rosterQ=$pdo->prepare("SELECT DISTINCT s.id FROM students s JOIN student_enrolments e ON e.student_id=s.id WHERE e.academic_year=:year AND e.form_level=:form AND COALESCE(e.stream,'')=:stream AND e.start_date<=:term_end AND (e.end_date IS NULL OR e.end_date>=:term_start)");$rosterQ->execute(['year'=>$assessment['academic_year'],'form'=>$assessment['form_level'],'stream'=>$assessment['stream'],'term_end'=>$assessment['ends_on'],'term_start'=>$assessment['starts_on']]);$roster=array_map('intval',$rosterQ->fetchAll(PDO::FETCH_COLUMN));$rosterSet=array_fill_keys($roster,true);$validStatuses=['Scored','Absent','Exempt'];$prepared=[];$counts=['Scored'=>0,'Absent'=>0,'Exempt'=>0];
foreach($scores as $studentId=>$entry){$studentId=filter_var($studentId,FILTER_VALIDATE_INT);if(!$studentId||!isset($rosterSet[$studentId])||!is_array($entry)){$_SESSION['error']='The mark list contains an invalid learner. Reload and try again.';header('Location: ../?page=academics&tab=assessments&id='.$assessmentId);exit;}$status=(string)($entry['status']??'');if($status==='')continue;if(!in_array($status,$validStatuses,true)){$_SESSION['error']='Select a valid mark status.';header('Location: ../?page=academics&tab=assessments&id='.$assessmentId);exit;}$mark=null;$grade=trim((string)($entry['grade']??''));$comment=trim((string)($entry['comment']??''));if(strlen($grade)>4||strlen($comment)>255){$_SESSION['error']='Grade or comment is too long.';header('Location: ../?page=academics&tab=assessments&id='.$assessmentId);exit;}if($status==='Scored'){$raw=trim((string)($entry['mark']??''));if($raw===''||!is_numeric($raw)||(float)$raw<0||(float)$raw>(float)$assessment['max_mark']){$_SESSION['error']='Enter a score within 0 and the assessment maximum, or mark the learner absent/exempt.';header('Location: ../?page=academics&tab=assessments&id='.$assessmentId);exit;}$mark=number_format((float)$raw,2,'.','');}else{$grade='';$comment=$comment?:ucfirst(strtolower($status));}$prepared[]=[$studentId,$status,$mark,$grade?:null,$comment?:null];$counts[$status]++;}
try{$pdo->beginTransaction();$upsert=$pdo->prepare('INSERT INTO assessment_marks (assessment_id,student_id,mark,mark_status,grade,comment) VALUES (:assessment,:student,:mark,:status,:grade,:comment) ON DUPLICATE KEY UPDATE mark=VALUES(mark),mark_status=VALUES(mark_status),grade=VALUES(grade),comment=VALUES(comment)');foreach($prepared as [$studentId,$status,$mark,$grade,$comment])$upsert->execute(['assessment'=>$assessmentId,'student'=>$studentId,'mark'=>$mark,'status'=>$status,'grade'=>$grade,'comment'=>$comment]);audit_log('assessment.marks_saved','assessments',(int)$assessmentId,['updated'=>count($prepared),'counts'=>$counts]);$pdo->commit();$_SESSION['notice']='Saved marks for '.count($prepared).' learner records.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Markbook save failed: '.$e->getMessage());$_SESSION['error']='Marks could not be saved. Please try again.';}
header('Location: ../?page=academics&tab=assessments&id='.$assessmentId);exit;
